// SITEMAP AND INIT
try {
  (function () {
    // Generated by Salesforce Data 360 Sitemap Builder

    console.log("[IP Debug] Sitemap script started");

    var SI = getSalesforceInteractions();

    SI.setLoggingLevel("debug");

    SI.init({
      consents: new Promise(resolve => {
        resolve([{
          provider: "Consent Provider",
          purpose: SI.ConsentPurpose.Tracking,
          status: SI.ConsentStatus.OptIn
        }]);
      }),

      personalization: {
        dataspace: "default"
      }

    }).then(async () => {

      console.log("[IP TEST] SDK INIT COMPLETED");
      const {
        cashDom,
        listener,
        resolvers,
        sendEvent,
        util,
        CartInteractionName,
        CatalogObjectInteractionName,
        OrderInteractionName
      } = SI;

      const currentURL = new URL(window.location.href);

      // ============================================================
      // DEV TEST: RETRIEVE VISITOR PUBLIC IP ADDRESS
      // Replace ipify with a Vodafone-approved endpoint
      // before production use.
      // ============================================================

      let visitorIpAddress = null;

      try {

        const response = await fetch(
          "https://api64.ipify.org?format=json"
        );

        if (response.ok) {

          const data = await response.json();

          visitorIpAddress = data.ip;

          console.log(
            "[IP Debug] Visitor IP retrieved:",
            visitorIpAddress
          );

          const ipTestInteraction = {
            name: "IP Address Test",
            eventType: "userEngagement",
            ipAddress: visitorIpAddress
          };

          console.log(
            "[IP Debug] Sending direct IP test:",
            ipTestInteraction
          );

          SI.sendEvent({
            interaction: ipTestInteraction
          });

        } else {

          console.error(
            "[IP Debug] IP lookup failed. HTTP status:",
            response.status
          );

        }

      } catch (error) {

        console.error(
          "[IP Debug] Unable to retrieve visitor IP:",
          error
        );

      }


      // ============================================================
      // GLOBAL CONFIGURATION
      // Adds retrieved IP to userEngagement events
      // ============================================================

      const global = {

        listeners: [],

        onActionEvent: actionEvent => {

          if (
            visitorIpAddress &&
            actionEvent.interaction &&
            actionEvent.interaction.eventType === "userEngagement"
          ) {

            actionEvent.interaction.ipAddress =
              visitorIpAddress;

            console.log(
              "[IP Debug] IP added to userEngagement:",
              actionEvent.interaction.ipAddress
            );

          }

          return actionEvent;
        }
      };


      // ============================================================
      // DEFAULT PAGE
      // ============================================================

      const pageTypeDefault = {

        name: "default",

        interaction: {
          name: "default",
          eventType: "userEngagement"
        }

      };


      // ============================================================
      // PAGE TYPES
      // ============================================================

      const pageTypes = [

        {
          name: "Home Page",

          isMatch: () =>
            window.location.pathname === "/",

          interaction: {
            name: "Page View",
            eventType: "userEngagement"
          }
        },


        {
          name: "Test MCP Page",

          isMatch: () =>
            window.location.pathname ===
            "/business/mcp/iphone18-duo",

          interaction: {
            name: "Page View",
            eventType: "userEngagement",
            ipAddress: visitorIpAddress
          },

          listeners: [

            // --------------------------------------------------------
            // SHOP IPHONE DUO CLICK
            // --------------------------------------------------------

            listener(
              "click",
              "#va42d5c24ef4ed8c35ca5f8852180b9c9b0d0546db2ed2b78966f073d8c13a0c4",
              () => {

                const interactionData = {
                  name: "Click - Shop iPhone Duo",
                  eventType: "userEngagement",
                  ipAddress: visitorIpAddress
                };

                console.log(
                  "[IP Debug] About to send interaction:",
                  interactionData
                );

                sendEvent({
                  interaction: interactionData
                });
              }
            ),


            // --------------------------------------------------------
            // CHAT NOW CLICK
            // --------------------------------------------------------

            listener(
              "click",
              "#v46840788e77c029c7fa4bf2ffafb483a52fa42a137c5aab1995aa96fe8465c1b",
              () => {

                sendEvent({
                  interaction: {
                    name: "Click - Chat Now",
                    eventType: "userEngagement",
                    ipAddress: visitorIpAddress
                  }
                });

              }
            )

          ]
        }

      ];


      // ============================================================
      // SITEMAP CONFIGURATION
      // ============================================================

      const sitemapConfig = {

        global: global,

        pageTypeDefault: pageTypeDefault,

        pageTypes: pageTypes

      };


      // ============================================================
      // CUSTOM EVENTS: PAGE SCROLL DEPTH
      // 25%, 50%, 75%, 100%
      // ============================================================

      const scrollThresholds = [
        25,
        50,
        75,
        100
      ];

      const scrollEventsSent = new Set();


      const pageScrollHandler = () => {

        const doc = document.documentElement;
        const body = document.body;

        const scrollTop =
          window.scrollY ||
          doc.scrollTop;

        const documentHeight = Math.max(
          doc.scrollHeight,
          doc.offsetHeight,
          body ? body.scrollHeight : 0,
          body ? body.offsetHeight : 0
        );

        const viewportHeight =
          window.innerHeight;

        const scrollableHeight =
          documentHeight - viewportHeight;


        // Detect bottom with small rounding allowance
        const isAtBottom =
          scrollTop + viewportHeight >=
          documentHeight - 5;


        // Calculate scroll percentage
        const scrollPercentage =
          scrollableHeight <= 0
            ? 100
            : Math.min(
              100,
              (scrollTop / scrollableHeight) * 100
            );


        console.log(
          "[Scroll Debug]",
          {
            scrollTop,
            viewportHeight,
            documentHeight,
            scrollPercentage:
              scrollPercentage.toFixed(2),
            isAtBottom
          }
        );


        scrollThresholds.forEach(threshold => {

          const reached =
            threshold === 100
              ? isAtBottom
              : scrollPercentage >= threshold;


          if (
            reached &&
            !scrollEventsSent.has(threshold)
          ) {

            scrollEventsSent.add(threshold);

            const eventName =
              `Page Scroll ${threshold}%`;

            console.log(
              "[Scroll Debug] Sending:",
              eventName
            );


            SI.sendEvent({
              interaction: {
                name: eventName,
                eventType: "userEngagement",
                ipAddress: visitorIpAddress
              }
            });

          }

        });

      };


      // Register scroll listener
      window.addEventListener(
        "scroll",
        pageScrollHandler,
        {
          passive: true
        }
      );


      console.log(
        "Page Scroll listeners registered"
      );


      // Check once during initialization
      pageScrollHandler();


      // ============================================================
      // INITIALIZE SITEMAP
      // ============================================================

      SI.initSitemap(
        sitemapConfig
      );

    });
  })()
} catch (e) {
  console.error("[Salesforce Data Cloud] Error loading sitemap:", e);
}